     <meta charset="utf-8" />
     <meta name="viewport" content="width=device-width, initial-scale=1" />
     <title>Cat FAQ — Meow &amp; Know</title>
     <style>
       :root {
         color-scheme: light;
         --bg: #f6f8fc;
         --panel: rgba(255, 255, 255, 0.82);
         --panel-strong: #ffffff;
         --text: #19202d;
         --muted: #5c6474;
         --border: rgba(25, 32, 45, 0.12);
         --accent: #5b6cff;
         --accent-soft: rgba(91, 108, 255, 0.12);
         --shadow: 0 24px 60px rgba(30, 41, 59, 0.12);
         --radius-xl: 28px;
         --radius-lg: 20px;
         --radius-md: 14px;
       }

       * {
         box-sizing: border-box;
       }

       html {
         scroll-behavior: smooth;
       }

       body {
         margin: 0;
         min-height: 100vh;
         font-family:
           Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
           "Segoe UI", sans-serif;
         line-height: 1.5;
         color: var(--text);
         background:
           radial-gradient(circle at top left, rgba(91, 108, 255, 0.16), transparent 34%),
           radial-gradient(circle at top right, rgba(255, 161, 100, 0.16), transparent 26%),
           linear-gradient(180deg, #f9fbff 0%, var(--bg) 100%);
       }

       a {
         color: inherit;
       }

       .skip-link {
         position: absolute;
         left: 1rem;
         top: 1rem;
         z-index: 10;
         padding: 0.75rem 1rem;
         border-radius: 999px;
         background: var(--panel-strong);
         border: 1px solid var(--border);
         transform: translateY(-180%);
         transition: transform 160ms ease;
         box-shadow: var(--shadow);
       }

       .skip-link:focus-visible {
         transform: translateY(0);
         outline: 3px solid var(--accent);
         outline-offset: 3px;
       }

       .page {
         width: min(1120px, calc(100% - 2rem));
         margin: 0 auto;
         padding: 1.25rem 0 3rem;
       }

       header {
         padding: 1.1rem 0 1.5rem;
       }

       .hero {
         display: grid;
         gap: 1.25rem;
         grid-template-columns: 1.35fr minmax(250px, 0.9fr);
         align-items: end;
         padding: clamp(1.25rem, 2vw, 2rem);
         border: 1px solid var(--border);
         border-radius: var(--radius-xl);
         background: var(--panel);
         box-shadow: var(--shadow);
         backdrop-filter: blur(18px);
       }

       .eyebrow {
         display: inline-flex;
         align-items: center;
         gap: 0.5rem;
         width: fit-content;
         margin: 0 0 0.85rem;
         padding: 0.35rem 0.8rem;
         border-radius: 999px;
         background: var(--accent-soft);
         color: #3f4de3;
         font-size: 0.875rem;
         font-weight: 650;
       }

       h1 {
         margin: 0;
         font-size: clamp(2.1rem, 4vw, 4rem);
         line-height: 0.98;
         letter-spacing: -0.04em;
       }

       .hero p {
         max-width: 60ch;
         margin: 0.9rem 0 0;
         color: var(--muted);
         font-size: 1.03rem;
       }

       .hero-card {
         padding: 1.1rem;
         border-radius: var(--radius-lg);
         background:
           linear-gradient(180deg, rgba(91, 108, 255, 0.11), rgba(91, 108, 255, 0.04)),
           #fff;
         border: 1px solid rgba(91, 108, 255, 0.16);
       }

       .hero-card strong {
         display: block;
         margin-bottom: 0.25rem;
         font-size: 1.05rem;
       }

       .hero-card p {
         margin: 0;
         color: var(--muted);
       }

       main {
         display: grid;
         gap: 1rem;
       }

       .faq-shell {
         padding: 0.3rem;
       }

       .faq-grid {
         display: grid;
         gap: 0.9rem;
       }

       .example {
         border-radius: var(--radius-lg);
       }

       .details {
         overflow: clip;
         border: 1px solid var(--border);
         border-radius: var(--radius-lg);
         background: var(--panel-strong);
         box-shadow: 0 16px 36px rgba(30, 41, 59, 0.08);
         transition:
           transform 160ms ease,
           border-color 160ms ease,
           box-shadow 160ms ease;
       }

       .details:hover {
         border-color: rgba(91, 108, 255, 0.26);
         box-shadow: 0 18px 42px rgba(30, 41, 59, 0.1);
       }

       .details[open] {
         border-color: rgba(91, 108, 255, 0.3);
         box-shadow: 0 20px 48px rgba(30, 41, 59, 0.1);
       }

       .details summary {
         list-style: none;
         cursor: pointer;
         display: flex;
         align-items: center;
         justify-content: space-between;
         gap: 1rem;
         padding: 1.15rem 1.25rem;
         font-weight: 650;
         font-size: 1.02rem;
       }

       .details summary::-webkit-details-marker {
         display: none;
       }

       .details summary::after {
         content: "+";
         display: grid;
         place-items: center;
         width: 2rem;
         height: 2rem;
         flex: 0 0 auto;
         border-radius: 999px;
         background: var(--accent-soft);
         color: #3140d7;
         font-size: 1.1rem;
         line-height: 1;
         transition: transform 160ms ease, background-color 160ms ease;
       }

       .details[open] summary::after {
         content: "–";
         transform: rotate(180deg);
         background: rgba(91, 108, 255, 0.18);
       }

       .details summary:hover {
         background: rgba(91, 108, 255, 0.03);
       }

       .details summary:focus-visible {
         outline: 3px solid var(--accent);
         outline-offset: -3px;
         border-radius: calc(var(--radius-lg) - 2px);
       }

       .details .answer {
         padding: 0 1.25rem 1.2rem;
         color: var(--muted);
       }

       .details .answer > :first-child {
         margin-top: 0;
       }

       .details .answer > :last-child {
         margin-bottom: 0;
       }

       .details .answer ul {
         margin: 0.75rem 0 0;
         padding-left: 1.15rem;
       }

       .details .answer li + li {
         margin-top: 0.35rem;
       }

       footer {
         padding: 1.4rem 0 0;
         color: var(--muted);
         font-size: 0.95rem;
         text-align: center;
       }

       .noscript {
         margin-top: 1rem;
         padding: 1rem 1.15rem;
         border-radius: var(--radius-md);
         border: 1px solid var(--border);
         background: rgba(255, 255, 255, 0.75);
       }

       @media (max-width: 780px) {
         .page {
           width: min(100% - 1rem, 1120px);
         }

         .hero {
           grid-template-columns: 1fr;
         }
       }

       @media (prefers-reduced-motion: reduce) {
         html {
           scroll-behavior: auto;
         }

         *,
         *::before,
         *::after {
           animation-duration: 0.01ms !important;
           animation-iteration-count: 1 !important;
           transition-duration: 0.01ms !important;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#maincontent">Skip to main content</a>

     <div class="page">
       <header>
         <div class="hero">
           <div>
             <div class="eyebrow">Cat FAQ</div>
             <h1>Everything you wanted to know about cats</h1>
             <p>
               A calm, quick-reference FAQ for curious cat people. Tap a question to expand the answer,
               or keep it collapsed to scan the page fast.
             </p>
           </div>

           <div class="hero-card" aria-label="Page summary">
             <strong>Designed for quick answers</strong>
             <p>
               Native disclosure controls keep the page keyboard-friendly, readable, and easy to browse
               on any screen size.
             </p>
           </div>
         </div>
       </header>

       <main id="maincontent">
         <section class="faq-shell" aria-labelledby="faq-heading">
           <h2 id="faq-heading" class="eyebrow">Frequently asked questions</h2>
           <div id="faq-root" class="faq-grid"></div>

           <noscript>
             <div class="noscript">
               <div class="faq-grid">
                 <div class="example">
                   <details class="details">
                     <summary>Why do cats purr?</summary>
                     <div class="answer">
                       <p>
                         Cats purr for more than one reason. It often signals comfort and contentment, but
                         many cats also purr when they are nervous, recovering, or trying to soothe themselves.
                       </p>
                     </div>
                   </details>
                 </div>
                 <div class="example">
                   <details class="details">
                     <summary>How much sleep do cats need?</summary>
                     <div class="answer">
                       <p>
                         Most adult cats sleep between 12 and 16 hours a day, and kittens can sleep even more.
                         Long naps are normal because cats conserve energy for short bursts of play and hunting.
                       </p>
                     </div>
                   </details>
                 </div>
                 <div class="example">
                   <details class="details">
                     <summary>Why do cats knead blankets and laps?</summary>
                     <div class="answer">
                       <p>
                         Kneading is a soothing behavior that starts in kittenhood. Adult cats often knead when
                         they feel safe, relaxed, or especially attached to a person or soft spot.
                       </p>
                     </div>
                   </details>
                 </div>
                 <div class="example">
                   <details class="details">
                     <summary>Do indoor cats need enrichment?</summary>
                     <div class="answer">
                       <p>
                         Yes. Indoor cats do best with climbing spaces, scratching posts, puzzle feeders, and
                         regular play sessions that let them stalk, chase, and pounce.
                       </p>
                     </div>
                   </details>
                 </div>
                 <div class="example">
                   <details class="details">
                     <summary>How should I introduce a new cat?</summary>
                     <div class="answer">
                       <p>
                         Start slowly with separate spaces, exchanged scents, and short supervised meetings.
                         Gradual introductions reduce stress and give both cats time to build confidence.
                       </p>
                     </div>
                   </details>
                 </div>
                 <div class="example">
                   <details class="details">
                     <summary>Why do cats bring home "gifts"?</summary>
                     <div class="answer">
                       <p>
                         Cats may bring prey or toys as a mix of instinct, practice, and social behavior. It is
                         not a present in the human sense, but it can be a sign that your cat feels bonded to you.
                       </p>
                     </div>
                   </details>
                 </div>
               </div>
             </div>
           </noscript>
         </section>
       </main>

       <footer>
         Built for cat people who like clear answers and good design.
       </footer>
     </div>

     <script>
       const faqItems = [
         {
           question: "Why do cats purr?",
           answer: [
             "Cats purr for more than one reason. It often signals comfort and contentment, but many cats also purr when they are nervous, recovering, or trying to soothe themselves.",
           ],
         },
         {
           question: "How much sleep do cats need?",
           answer: [
             "Most adult cats sleep between 12 and 16 hours a day, and kittens can sleep even more. Long naps are normal because cats conserve energy for short bursts of play and hunting.",
           ],
         },
         {
           question: "Why do cats knead blankets and laps?",
           answer: [
             "Kneading is a soothing behavior that starts in kittenhood. Adult cats often knead when they feel safe, relaxed, or especially attached to a person or soft spot.",
           ],
         },
         {
           question: "Do indoor cats need enrichment?",
           answer: [
             "Yes. Indoor cats do best with climbing spaces, scratching posts, puzzle feeders, and regular play sessions that let them stalk, chase, and pounce.",
           ],
         },
         {
           question: "How should I introduce a new cat?",
           answer: [
             "Start slowly with separate spaces, exchanged scents, and short supervised meetings. Gradual introductions reduce stress and give both cats time to build confidence.",
           ],
         },
         {
           question: 'Why do cats bring home "gifts"?',
           answer: [
             "Cats may bring prey or toys as a mix of instinct, practice, and social behavior. It is not a present in the human sense, but it can be a sign that your cat feels bonded to you.",
           ],
         },
       ];

       function FaqItem({ question, answer }) {
         return `
           <div class="example">
             <details class="details">
               <summary>${question}</summary>
               <div class="answer">
                 ${answer.map((paragraph) => `<p>${paragraph}</p>`).join("")}
               </div>
             </details>
           </div>
         `;
       }

       function FaqList(items) {
         return items.map((item) => FaqItem(item)).join("");
       }

       function App() {
         return FaqList(faqItems);
       }

       document.getElementById("faq-root").innerHTML = App();
     </script>
   </body>
 </html>

')
